'use strict';
/**
 * The OpenRouter model catalogue: fetched, cached, and honest about which.
 *
 * The catalogue endpoint is PUBLIC — no key, no spend, no account. Verified:
 * 445 models, 377 of them declaring tool support. So the browser works before
 * the council has a key, and a key never needs to exist for it to keep working.
 *
 * CACHED TO DISK ON PURPOSE, and the cache is the point rather than an
 * optimisation:
 *
 *   - the panel opens instantly instead of after a network round trip
 *   - it works with no network at all, which is the ordinary case on a plane
 *     or behind a flaky connection
 *   - the catalogue changes a few times a week, not a few times a second
 *
 * WHAT IT REFUSES TO DO IS PRETEND. Every result says where it came from and
 * how old it is, because a stale price shown as current is the failure that
 * costs money: a model that was free last month and is not any more would keep
 * reading as free forever. `stale` and `fetchedAt` travel with the data so the
 * panel can say "prices from 3 days ago" instead of implying they are live.
 *
 * NO API KEY IS EVER SENT HERE. This endpoint does not take one, and sending a
 * key to an endpoint that does not need it is how keys end up in logs.
 */

const https = require('https');
const fsp = require('fs/promises');
const { renameWithRetryAsync } = require('./atomic-write');
const path = require('path');

const CATALOGUE_URL = 'https://openrouter.ai/api/v1/models';

// A few times a week is how often this actually changes. An hour keeps a long
// session from re-fetching while still noticing a new model the same day.
const FRESH_MS = 60 * 60 * 1000;

const REQUEST_TIMEOUT_MS = 15000;

// The catalogue is ~1MB of JSON. A ceiling so a wrong endpoint or a captive
// portal cannot stream indefinitely into memory.
const MAX_BYTES = 8 * 1024 * 1024;

function fetchCatalogue(url = CATALOGUE_URL) {
  return new Promise((resolve, reject) => {
    const req = https.get(url, { timeout: REQUEST_TIMEOUT_MS }, (res) => {
      if (res.statusCode !== 200) {
        res.resume();
        reject(new Error(`catalogue returned HTTP ${res.statusCode}`));
        return;
      }
      let body = '';
      let bytes = 0;
      res.setEncoding('utf8');
      res.on('data', (chunk) => {
        bytes += Buffer.byteLength(chunk);
        if (bytes > MAX_BYTES) {
          req.destroy();
          reject(new Error('catalogue response exceeded the size ceiling'));
          return;
        }
        body += chunk;
      });
      res.on('end', () => {
        try {
          const parsed = JSON.parse(body);
          const rows = parsed && Array.isArray(parsed.data) ? parsed.data : null;
          if (!rows) {
            reject(new Error('catalogue response had no data array'));
            return;
          }
          resolve(rows);
        } catch (err) {
          reject(new Error(`catalogue response was not JSON: ${err.message}`));
        }
      });
    });
    req.on('timeout', () => { req.destroy(new Error('catalogue request timed out')); });
    req.on('error', reject);
  });
}

async function readCache(file) {
  try {
    const parsed = JSON.parse(await fsp.readFile(file, 'utf8'));
    if (!parsed || !Array.isArray(parsed.rows) || !parsed.rows.length) return null;
      // A missing or unusable timestamp is NULL, not 0. Zero only looks ancient
      // because the epoch is far away, which makes the freshness rule depend on
      // an accident of arithmetic rather than on saying what it means. Null is
      // "we do not know when this was fetched", and that is never fresh.
    const stamp = Number(parsed.fetchedAt);
    return { rows: parsed.rows, fetchedAt: Number.isFinite(stamp) && stamp > 0 ? stamp : null };
  } catch {
    return null;
  }
}

async function writeCache(file, rows, now) {
  try {
    await fsp.mkdir(path.dirname(file), { recursive: true });
    // Written via a temp file and renamed: a half-written cache that still
    // parses would be a truncated catalogue silently presented as the whole one.
    const tmp = `${file}.tmp`;

    // The temp is cleaned up on failure, like the other two write-and-rename
    // sites. Miguel: the cleanup landed at two of three, and one site
    // differing is how the next reader concludes the pattern is optional.
    // Harmless here on its own -- the fixed `.tmp` name bounds it at one
    // orphan and a model catalogue holds no secrets -- which is precisely why
    // the reason to do it is consistency rather than risk.
    try {
      await fsp.writeFile(tmp, JSON.stringify({ fetchedAt: now, rows }), 'utf8');
      // Retried. Dexter, Finding 5: this is the third write-and-rename in the
      // codebase and was the only one left unretried, precisely BECAUSE it
      // never threw -- the catch below swallowed it. On the machine the retry
      // exists for, a handle is briefly held on every write, so this rename
      // failed every time, the cache was never written at all, and every
      // launch silently paid a network fetch.
      //
      // The ASYNC sibling, not renameWithRetry: this caller can yield, so it
      // must, rather than freezing the event loop the way Atomics.wait does.
      await renameWithRetryAsync(tmp, file);
    } catch (err) {
      try { await fsp.unlink(tmp); } catch { /* best effort, as elsewhere */ }
      throw err;
    }
  } catch (err) {
    // A cache that cannot be written is a slower panel, not a broken one, so
    // this still degrades rather than throwing. But it SAYS SO now.
    //
    // Miguel: the retry above removed the CAUSE and left the DETECTOR missing.
    // An empty catch makes an exhausted write indistinguishable from a working
    // cache -- the hidden outage Finding 5 was about, every launch paying a
    // network fetch forever with nothing reporting it. Degrading is right;
    // degrading undetectably is the bug.
    //
    // COST, worth knowing: writeCache is awaited on the network path, so on a
    // machine where the rename fails PERMANENTLY every refresh now pays the
    // full 300ms backoff before loadCatalogue resolves, where it previously
    // paid none. Justified while the failure is transient -- that is the fix --
    // and pure cost when it is permanent, which is a second reason this
    // warning matters: 300ms of silence is worse than 0ms of silence.
    console.warn('[openrouter] could not write the catalogue cache:', err && err.message);
  }
}


/**
 * The catalogue, with its provenance.
 *
 * Returns `{ rows, source, fetchedAt, stale, error }` where source is
 * 'network' | 'cache' | 'none'. `rows` is raw — host/models.js decides what a
 * row means.
 *
 * A network failure with a cache present is NOT an error the caller has to
 * handle: it returns the cache, marked stale, with the reason attached. A
 * network failure with no cache returns an empty list and says so, rather than
 * an empty list that looks like "OpenRouter offers no models".
 */
async function loadCatalogue({ cacheFile, now = Date.now(), force = false, fetchImpl = fetchCatalogue } = {}) {
  const at = typeof now === 'function' ? now() : now;
  const cached = cacheFile ? await readCache(cacheFile) : null;

  if (!force && cached && cached.fetchedAt !== null && at - cached.fetchedAt < FRESH_MS) {
    return { rows: cached.rows, source: 'cache', fetchedAt: cached.fetchedAt, stale: false, error: null };
  }

  try {
    const rows = await fetchImpl();
    if (cacheFile) await writeCache(cacheFile, rows, at);
    return { rows, source: 'network', fetchedAt: at, stale: false, error: null };
  } catch (err) {
    const message = (err && err.message) || String(err);
    if (cached) {
        // Stale beats empty, but only if it SAYS it is stale. A month-old price
        // shown as current is the failure that costs money.
      return {
        rows: cached.rows, source: 'cache', fetchedAt: cached.fetchedAt,
        stale: true, error: message,
      };
    }
      // Empty AND an error, never a bare empty list: "no models" and "could not
      // ask" look identical on screen otherwise.
    return { rows: [], source: 'none', fetchedAt: 0, stale: true, error: message };
  }
}

module.exports = { loadCatalogue, fetchCatalogue, CATALOGUE_URL, FRESH_MS };

host/port-for-project.js.source:
'use strict';
/**
 * Which port does this project's host live on?
 *
 * Derived from the path rather than allocated, so that closing a window and
 * reopening it finds the host it left running -- with no registry to keep in
 * step, and no ordering dependency between two projects opened at once.
 *
 * Derivation is not a guarantee of uniqueness and is not treated as one: two
 * projects can hash to the same port, so the caller probes and steps. What the
 * hash buys is STABILITY, not exclusivity -- the same project lands on the same
 * port every time, and the handshake decides whether the occupant is ours.
 */

const { normalizeProjectPath } = require('./project-path');
const { decideAttach } = require('./handshake');

// Deliberately NOT 7681, the port this app used when it could only serve one
// project. 7681 is also ttyd's default, so leaving the old single-project
// default where it was keeps the collision confined to one well-known port
// rather than spreading it across the derived range.
const PORT_BASE = 7700;
const PORT_SPAN = 100;

function portForCwd(cwd) {
  const key = normalizeProjectPath(cwd);
  if (key === null) {
    throw new Error(`portForCwd: need a project path, got ${JSON.stringify(cwd)}`);
  }
  // FNV-ish rolling hash. Nothing here is security-sensitive -- it picks a
  // starting point for a probe -- so cheap and stable beats strong.
  let h = 0;
  for (let i = 0; i < key.length; i++) h = (h * 31 + key.charCodeAt(i)) >>> 0;
  return PORT_BASE + (h % PORT_SPAN);
}

/**
 * The port this project should actually use, and what to do when we get there.
 *
 * Walks from the derived port through the range, taking the first port that is
 * either free or already serving THIS project. A refusal of any kind -- another
 * project, or an occupant that would not identify itself -- steps to the next
 * one, because both mean "not ours" and neither is the user's problem to solve.
 *
 * Bounded by construction: exactly PORT_SPAN probes, then an error. An
 * unbounded probe here is a silent hang in the first command a new user runs.
 */
// A wall-clock ceiling on the whole walk, not just a count of attempts.
// Dexter F12: app/main.js probes with a 400ms socket timeout, so behind a
// DROP-style firewall rule PORT_SPAN attempts is 40 SECONDS before the window
// opens -- and the header promises a bound precisely so there is no hang. An
// iteration count bounds the wrong axis. 6s is comfortably more than a healthy
// resolve (microseconds) and far less than a user's patience with a blank
// screen.
const DEADLINE_MS = 6000;

async function resolvePort({ cwd, occupantAt, deadlineMs = DEADLINE_MS } = {}) {
  const first = portForCwd(cwd);
  const giveUpAt = Date.now() + deadlineMs;
  for (let i = 0; i < PORT_SPAN; i++) {
    if (Date.now() > giveUpAt) {
      throw new Error(
        `resolvePort: probing for a free port took too long (>${deadlineMs}ms, ` +
        `${i} of ${PORT_SPAN} ports tried) -- something is dropping connections on ` +
        `${PORT_BASE}-${PORT_BASE + PORT_SPAN - 1}`);
    }
    const port = PORT_BASE + ((first - PORT_BASE + i) % PORT_SPAN);
    // Awaited because the real probe opens a socket. A synchronous answer --
    // which is what every test injects -- passes through await unchanged.
    const { action } = decideAttach({ requestedCwd: cwd, occupant: await occupantAt(port) });
    if (action === 'spawn' || action === 'attach') return { port, action };
  }
  throw new Error(
    `resolvePort: no free port for ${cwd} in ${PORT_BASE}-${PORT_BASE + PORT_SPAN - 1}`,
  );
}

module.exports = { portForCwd, resolvePort, PORT_BASE, PORT_SPAN, DEADLINE_MS };

host/project-path.js.source:
'use strict';
/**
 * Is this the same project folder?
 *
 * Two private normalizers already exist in this codebase and neither is
 * exported: `host/themes.js` lowercases (it matches registry keys), and
 * `host/fog.js` does not (it must preserve case to build relative paths for
 * display). They differ deliberately, so this is a third primitive rather than
 * a refactor of either -- the handshake needs one specific question answered,
 * `are these the same folder`, and needs it to fail closed.
 *
 * Windows semantics, because that is where this runs: the path is RESOLVED,
 * then separators are made interchangeable, a trailing separator means
 * nothing, and case means nothing.
 *
 * WHAT THIS STILL DOES NOT HANDLE, named so the header is not read as a
 * completeness claim (Dexter, PR #31 Finding 5): trailing dots and spaces,
 * which Win32 strips and Node does not; 8.3 short names (VIBECO~1); UNC versus
 * a mapped drive letter; and the \\?\ prefix. In the other direction, JS
 * `toLowerCase` is Unicode folding rather than the NTFS upcase table, so
 * U+0130 can fold two genuinely distinct directories together, as can a
 * directory flagged case-sensitive.
 *
 * The honest fix for all of those is a device+file-id comparison
 * (`fs.statSync().dev` / `.ino`), the only thing that gets junctions, 8.3 and
 * UNC-vs-mapped right in one move -- but it needs BOTH paths to exist, and
 * this is called on paths that may not. That is a design change rather than a
 * patch, and it is left as a follow-up instead of guessed at.
 */

const path = require('path');

// Absence is not a path. Returning null here rather than the string 'null' is
// the whole reason `samePath(null, null)` is false: a coercing compare makes
// two missing values agree, and the handshake would then attach to a host
// whose project it could not identify.
function normalizeProjectPath(p) {
  if (typeof p !== 'string' || !p.trim()) return null;

  // RESOLVE FIRST. Without it the three transforms below miss everything
  // structural -- an unresolved `..`, a `.` segment, doubled separators
  // mid-path -- and each miss made `decideAttach` answer 'other-project',
  // which made `resolvePort` step, which started a SECOND host and a second
  // permission-bypassed claude in a folder that already had one.
  //
  // `path.resolve` is pure string arithmetic and never touches the disk, so
  // this stays safe on paths that do not exist, which samePath must support.
  let resolved;
  try {
    resolved = path.resolve(p);
  } catch {
    return null;                        // a path resolve refuses is not a path
  }

  const out = resolved.replace(/\\/g, '/').replace(/\/+$/, '').toLowerCase();

  // A path that normalizes away to nothing is ABSENT, not the empty string
  // (Finding 14). Callers test `=== null`, so '' would be a value that is
  // neither absent nor a path -- and portForCwd('') would hash it to a real
  // port quite happily.
  return out === '' ? null : out;
}

function samePath(a, b) {
  const x = normalizeProjectPath(a);
  const y = normalizeProjectPath(b);
  if (x === null || y === null) return false;
  return x === y;
}

/**
 * What to call a window showing this project. FF3.
 *
 * The window was titled `claude-custom — spike/terminal-fidelity`, hardcoded,
 * and still naming a spike branch. Once multi-project means two windows can be
 * open at once, the title is the ONLY thing distinguishing them in the taskbar,
 * in alt-tab, and in a thumbnail.
 *
 * Pure, and here rather than in main.js, because every interesting case is a
 * path edge case and none of them are reachable from a test inside main.js.
 * `path.basename` returns '' for a drive root and for a bare separator, and an
 * empty title is a window with no identity at all — worse than the long form
 * it replaces.
 */
function projectLabel(p) {
  if (typeof p !== 'string' || !p.trim()) return 'claude-custom';
  const trimmed = p.trim();
  // `win32` explicitly, not the ambient `path`. Miguel, PR #33, A10: on a
  // POSIX runner `path.basename('C:\\Users\\x\\proj')` returns the whole string, so
  // both this function and its five tests silently depended on which
  // machine ran them. win32.basename treats / and \\ alike, so it is
  // strictly the more permissive of the two and correct for a harness
  // whose own header says Windows is where it runs.
  //
  // No trailing-separator strip: A9, measured -- basename already does it,
  // and the class that was here (`[\\/]`) held only a forward slash, so it
  // would not have stripped a backslash even if it had been needed. Dead
  // code that read as load-bearing, credited in the doc comment above.
  const base = path.win32.basename(trimmed);
  if (base) return base;
  // A drive root, a bare separator, or anything else basename cannot name.
  return trimmed;
}

module.exports = { samePath, normalizeProjectPath, projectLabel };

